head.script:
scwin.screenId = "jldinf90900";

///////// 1. 변수 및 선언 영역 /////////

scwin.id_button = $c.util.getComponent('id_button');


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isuNm", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isuNm"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const apct_tel_no = $c.util.getComponent('ipt_apctTelNo').getValue();
        const apct_fax_no = $c.util.getComponent('ipt_apctFaxNo').getValue();
        const encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail').getValue();
        const encryp_cellphone_no = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
        const arrayTel = apct_tel_no.split("-");
        const arrayFax = apct_fax_no.split("-");
        const arrayEmail = encryp_apct_email.split("@");
        const arrayHp = encryp_cellphone_no.split("-");
        for (var i = 0; i < arrayTel.length; i++) {
            $("#apct_tel_no_" + (i + 1)).val(arrayTel[i]);
        }
        for (var i = 0; i < arrayFax.length; i++) {
            $("#apct_fax_no_" + (i + 1)).val(arrayFax[i]);
        }
        for (var i = 0; i < arrayEmail.length; i++) {
            $("#encryp_apct_email_" + (i + 1)).val(arrayEmail[i]);
        }
        for (var i = 0; i < arrayHp.length; i++) {
            $("#encryp_cellphone_no_" + (i + 1)).val(arrayHp[i]);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90900.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf90900.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

