///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_send_form = async function () {
    const sbmOptions = {
        id: "tx_send_form",
        method: "post",
        action: "/common/stdcdDel.do?method=stdcdDelProc",
        ref: "dma_sendFormReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf90900.tx_send_form" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.emailCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name scwin.setInsurInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.setInsurInfo = function (obj) {
    /* sdd-asis-lifecycle:begin setInsurInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const com_nm = $c.util.getComponent('ipt_comNm').getValue();
    if (obj === "1") {
        $c.util.getComponent('ipt_applComNm').setValue(com_nm);
    } else {
        $c.util.getComponent('ipt_applComNm').setValue("");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.send_form = async function () {
    /* sdd-asis-lifecycle:begin send_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = $c.util.getComponent('ipt_delRsn').getValue(); if (str == null) { str = ''; }
    const len = $c.str.getByteLength(str);
    if (str === "") {
        await $c.win.alert("삭제신청사유를 입력해 주십시오");
        $c.util.getComponent("ipt_delRsn").focus();
        return;
    }
    if (len < 10) {
        await $c.win.alert("삭제신청사유는 한글 5자, 영문 10자 이상 입력해 주십시오");
        $c.util.getComponent("ipt_delRsn").focus();
        return;
    }
    if (len > 60) {
        await $c.win.alert("삭제신청사유는 한글30자, 영문60자 이내로 입력해 주십시오.");
        $c.util.getComponent("ipt_delRsn").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) == 0) {
        await $c.win.alert("신청인 소속기관을 입력해 주십시오");
        $c.util.getComponent("ipt_applComNm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_applComNm').getValue()) > 60) {
        await $c.win.alert("신청인 소속기관을 한글 30자, 영문 60자이내로 입력해 주십시오");
        $c.util.getComponent("ipt_applComNm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) == 0) {
        await $c.win.alert("신청인 이름을 입력해 주십시오");
        $c.util.getComponent("ipt_apctNm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) > 20) {
        await $c.win.alert("신청인 이름을 한글 10자, 영문 20자이내로 입력하세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo1').getValue()) == 0) {
        await $c.win.alert("신청인 전화번호를 입력해 주십시오");
        $c.util.getComponent("ipt_apctTelNo1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo2').getValue()) == 0) {
        await $c.win.alert("신청인 전화번호를 입력해 주십시오");
        $c.util.getComponent("ipt_apctTelNo2").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo3').getValue()) == 0) {
        await $c.win.alert("신청인 전화번호를 입력해 주십시오");
        $c.util.getComponent("ipt_apctTelNo3").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue()) == 0) {
        await $c.win.alert("신청인 이메일을 입력해 주십시오");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail2').getValue()) == 0) {
        await $c.win.alert("신청인 이메일을 입력해 주십시오");
        $c.util.getComponent("ipt_encrypApctEmail2").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue() + "@" + $c.util.getComponent('ipt_encrypApctEmail2').getValue()) > 40) {
        await $c.win.alert("신청인 이메일을 한글 20자, 영문 40자이내로 입력해 주십시오");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()) == 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력해 주십시오");
        $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo2').getValue()) == 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력해 주십시오");
        $c.util.getComponent("ipt_encrypCellphoneNo2").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo3').getValue()) == 0) {
        await $c.win.alert("신청인 휴대전화번호를 입력해 주십시오");
        $c.util.getComponent("ipt_encrypCellphoneNo3").focus();
        return;
    }
    const apct_tel_no = $c.util.getComponent('ipt_apctTelNo1').getValue() + "-" + $c.util.getComponent('ipt_apctTelNo2').getValue() + "-" + $c.util.getComponent('ipt_apctTelNo3').getValue();
    const apct_fax_no = $c.util.getComponent('ipt_apctFaxNo1').getValue() + "-" + $c.util.getComponent('ipt_apctFaxNo2').getValue() + "-" + $c.util.getComponent('ipt_apctFaxNo3').getValue();
    const encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail1').getValue() + "@" + $c.util.getComponent('ipt_encrypApctEmail2').getValue();
    const encryp_cellphone_no = $c.util.getComponent('ipt_encrypCellphoneNo1').getValue() + "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue() + "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue();
    $c.util.getComponent('ipt_apctTelNo').setValue(apct_tel_no);
    $c.util.getComponent('ipt_apctFaxNo').setValue(apct_fax_no);
    $c.util.getComponent('ipt_encrypApctEmail').setValue(encryp_apct_email);
    $c.util.getComponent('ipt_encrypCellphoneNo').setValue(encryp_cellphone_no);
    if (await $c.win.confirm("삭제신청 하시겠습니까?")) {
        scwin.id_button.setStyle("display", "none");
        const form = (document.JLDINF90900 || { elements: [] });
        form.action = "/common/stdcdDel.do?method=stdcdDelProc";
        await scwin.tx_send_form();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk_chrg_nm
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.chk_chrg_nm = async function (fm) {
    /* sdd-asis-lifecycle:begin chk_chrg_nm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
    /* sdd-asis-lifecycle:end */
};
